content:
基础指针指针本质就是一个变量，只不过它存的不是普通的数值，而是另一个变量的内存地址。
int a = 42;int* p = &amp;a;  // p 存的是 a 的地址


&amp;a — 取地址，拿到 a 在内存中的位置
*p — 解引用，通过地址找到那个位置上存的值

#include &lt;iostream&gt;std::cout &lt;&lt; p;   // 输出地址，类似 0x2000std::cout &lt;&lt; *p;  // 输出 42

修改 *p 就是在修改 a 本身：
#include &lt;iostream&gt;*p = 100;std::cout &lt;&lt; a;  // 100

声明时注意初始化，未初始化的指针指向随机地址，解引用就是未定义行为：
int* bad;       // 危险：指向未知地址int* safe = nullptr;  // 安全：明确表示&quot;不指向任何东西&quot;

内存
内存可以看作一大片连续编号的字节，编号就是地址
每个变量都在内存里占一小段位置，&amp;a 拿到的是这段位置的起始地址
占多大由类型决定：int 通常 4 字节、double 通常 8 字节。可以用 sizeof 查：

#include &lt;iostream&gt;std::cout &lt;&lt; sizeof(int);     // 通常 4std::cout &lt;&lt; sizeof(double);  // 通常 8

程序运行时的内存大致分几个区域，指针可以指向其中任意一块：

栈：局部变量，离开作用域自动销毁
堆：new 分配出来的，需要手动 delete
静态区：全局变量、static 变量，程序运行期间一直存在
代码区：程序指令本身

堆 vs 栈判断一个变量（普通数组、指针数组都一样）在堆还是栈，唯一的依据是它是怎么创建的，而不是它指向谁：

局部变量、局部数组 → 栈，离开作用域自动销毁
new &#x2F; new[] 出来的 → 堆，必须手动 delete

void demo() &#123;    int a[3] = &#123;1, 2, 3&#125;;            // 普通局部数组 → 栈    int x = 1, y = 2, z = 3;    int* ptrs[3] = &#123;&amp;x, &amp;y, &amp;z&#125;;     // 指针数组：数组本身在栈，指向的 x/y/z 也在栈    int* heap_ptrs[3];    for (int i = 0; i &lt; 3; i++)        heap_ptrs[i] = new int(i);   // 数组本身仍在栈，但每个元素指向的内容在堆    // 用完要逐个 delete heap_ptrs[i]，数组本身不用管    int* p = new int[3];             // p 这个指针在栈，但它指向的数组在堆    delete[] p;&#125;

关键：指针自己放在哪，和被它指向的对象在哪，是两回事。



写法
变量&#x2F;数组本身
它（们）指向的内容



int a[3];
栈
—（元素是 int 值，直接存在数组里）


int* ptrs[3];
栈
看每个指针怎么初始化，可能在栈也可能在堆


int* p = new int[3];
指针在栈
数组在堆


另外：栈空间有限（通常几 MB），大数组别直接放栈上，容易栈溢出；堆空间大得多，大块内存要用 new 去堆上分配。

指针与数组用指针遍历数组数组名本身就可以当作指向首元素的指针：
#include &lt;iostream&gt;int arr[] = &#123;10, 20, 30, 40, 50&#125;;int* p = arr;  // 等价于 int* p = &amp;arr[0];for (int i = 0; i &lt; 5; i++) &#123;    std::cout &lt;&lt; *(p + i) &lt;&lt; &quot; &quot;;  // 10 20 30 40 50&#125;

注意：p + i 不是地址加 i 个字节，而是加 i 个元素的大小。如果 int 是 4 字节，p + 1 实际上地址偏移了 4 字节。
指针算术#include &lt;iostream&gt;int arr[] = &#123;10, 20, 30, 40, 50&#125;;int* p = arr;p++;        // 现在指向 arr[1]p += 2;     // 现在指向 arr[3]int* q = &amp;arr[4];std::cout &lt;&lt; q - p;  // 1，两个指针之间隔了 1 个元素

常见写法——用指针做循环：
#include &lt;iostream&gt;int arr[] = &#123;1, 2, 3, 4, 5&#125;;for (int* p = arr; p &lt; arr + 5; p++) &#123;    std::cout &lt;&lt; *p &lt;&lt; &quot; &quot;;&#125;

这和标准库迭代器的设计思路一致：[begin, end) 左闭右开区间。
函数传参：指针 vs 引用用指针修改外部变量C 语言时代只能用指针实现”在函数里改外面的变量”：
void swap(int* a, int* b) &#123;    int tmp = *a;    *a = *b;    *b = tmp;&#125;int x = 1, y = 2;swap(&amp;x, &amp;y);  // 调用时要手动取地址

C++ 有了引用，同样的功能写起来更干净：
void swap(int&amp; a, int&amp; b) &#123;    int tmp = a;    a = b;    b = tmp;&#125;int x = 1, y = 2;swap(x, y);  // 调用时不需要 &amp;

选择建议：

能用引用就用引用，语法更清晰
需要表达”可能为空”时用指针（引用必须绑定到有效对象）
和 C 接口交互时用指针

传数组给函数数组传参时会退化为指针，必须额外传长度：
#include &lt;iostream&gt;void printArray(int* arr, int size) &#123;    for (int i = 0; i &lt; size; i++) &#123;        std::cout &lt;&lt; arr[i] &lt;&lt; &quot; &quot;;    &#125;&#125;int data[] = &#123;1, 2, 3, 4, 5&#125;;printArray(data, 5);

现代 C++ 更推荐用 std::span（C++20）或传 std::vector&amp;，避免指针加长度的手动管理。
用 std::span——数组和 vector 都能直接传，长度由 span 自己维护：
#include &lt;iostream&gt;#include &lt;span&gt;#include &lt;vector&gt;void printArray(std::span&lt;const int&gt; s) &#123;    for (int x : s) &#123;        std::cout &lt;&lt; x &lt;&lt; &quot; &quot;;    &#125;&#125;int data[] = &#123;1, 2, 3, 4, 5&#125;;printArray(data);               // 数组自动推导长度std::vector&lt;int&gt; v&#123;1, 2, 3&#125;;printArray(v);                  // vector 也能直接传

用 const std::vector&lt;int&gt;&amp;——长度由 vector 自己维护：
#include &lt;iostream&gt;#include &lt;vector&gt;void printArray(const std::vector&lt;int&gt;&amp; v) &#123;    for (int x : v) &#123;        std::cout &lt;&lt; x &lt;&lt; &quot; &quot;;    &#125;&#125;std::vector&lt;int&gt; data&#123;1, 2, 3, 4, 5&#125;;printArray(data);               // 不需要单独传 size

如果拿到的本来就是 C 数组（例如和 C 库交互），std::span 是更合适的桥接方式。
动态内存：new &#x2F; delete分配与释放栈上的变量出了作用域自动销毁，但有时候需要对象活得更久，或者大小在运行时才知道：
#include &lt;iostream&gt;// 分配单个对象int* p = new int(42);std::cout &lt;&lt; *p;  // 42delete p;         // 用完必须释放// 分配数组int* arr = new int[100];arr[0] = 1;delete[] arr;     // 数组用 delete[]，不是 delete

规则：new 对应 delete，new[] 对应 delete[]，混用是未定义行为。
内存泄漏的典型场景void leak() &#123;    int* p = new int(42);    // 忘了 delete，函数返回后 p 没了，但内存没释放&#125;

void earlyReturn() &#123;    int* p = new int[100];    if (someCondition) &#123;        return;  // 提前返回，delete[] 被跳过    &#125;    delete[] p;&#125;

void exceptionLeak() &#123;    int* p = new int[100];    riskyFunction();  // 如果抛异常，下面的 delete[] 执行不到    delete[] p;&#125;

这些场景就是智能指针要解决的问题。
智能指针智能指针是对裸指针的封装，利用 RAII（资源获取即初始化）机制在离开作用域时自动释放内存。需要 #include &lt;memory&gt;。
unique_ptr独占所有权，同一时刻只有一个 unique_ptr 指向对象：
#include &lt;iostream&gt;#include &lt;memory&gt;auto p = std::make_unique&lt;int&gt;(42);std::cout &lt;&lt; *p;  // 42// 离开作用域自动释放，不需要 delete

不能复制，但可以移动：
#include &lt;memory&gt;#include &lt;utility&gt;auto p1 = std::make_unique&lt;int&gt;(42);// auto p2 = p1;            // 编译错误：不能复制auto p2 = std::move(p1);   // OK：p1 变为 nullptr，所有权转给 p2

shared_ptr多个指针共享同一个对象，内部维护引用计数，最后一个 shared_ptr 销毁时释放内存：
#include &lt;iostream&gt;#include &lt;memory&gt;auto p1 = std::make_shared&lt;int&gt;(42);auto p2 = p1;  // 引用计数变为 2std::cout &lt;&lt; p1.use_count();  // 2p1.reset();    // p1 放弃所有权，计数变为 1// p2 销毁时计数归零，内存释放

适用场景：对象的生命周期不确定由谁管理，比如缓存、观察者模式中的共享资源。
代价是引用计数带来的额外开销，别无脑用。
weak_ptrweak_ptr 是 shared_ptr 的搭档，不增加引用计数，只是”观察”一个 shared_ptr 管理的对象：
#include &lt;iostream&gt;#include &lt;memory&gt;auto sp = std::make_shared&lt;int&gt;(42);std::weak_ptr&lt;int&gt; wp = sp;   // 不影响引用计数std::cout &lt;&lt; sp.use_count();  // 仍是 1// 用之前要先 lock()，拿到一个临时的 shared_ptrif (auto p = wp.lock()) &#123;    std::cout &lt;&lt; *p;          // 42&#125; else &#123;    // 对象已经被释放了&#125;

主要用途是打破 shared_ptr 的循环引用。两个对象互相持有对方的 shared_ptr 时，引用计数永远不为 0，谁都不会被释放，造成泄漏：
#include &lt;memory&gt;struct Node &#123;    std::shared_ptr&lt;Node&gt; next;&#125;;auto a = std::make_shared&lt;Node&gt;();auto b = std::make_shared&lt;Node&gt;();a-&gt;next = b;b-&gt;next = a;   // 互相引用 → 引用计数永远 &gt;= 1，内存泄漏// 把其中一个改成 weak_ptr 即可打破循环struct Node2 &#123;    std::weak_ptr&lt;Node2&gt; next;   // 关键：成员用 weak_ptr，不增加引用计数&#125;;auto a2 = std::make_shared&lt;Node2&gt;();auto b2 = std::make_shared&lt;Node2&gt;();a2-&gt;next = b2;   // 赋值到 weak_ptr，不会增加计数b2-&gt;next = a2;   // 同样不增加计数 → 作用域结束 a2、b2 正常释放

判断标准：只是”借用&#x2F;观察”对象而不想延长它的生命，就用 weak_ptr。

现代 C++ 标准库的核心就是 unique_ptr &#x2F; shared_ptr &#x2F; weak_ptr 三个（auto_ptr 已被移除），日常开发记住它们的定位即可：独占、共享、观察。

常见问题野指针 &#x2F; 悬垂指针#include &lt;iostream&gt;// 悬垂指针：指向已释放的内存int* p = new int(42);delete p;std::cout &lt;&lt; *p;  // 未定义行为！内存已归还，可能读到垃圾值或崩溃// 防御：释放后置空delete p;p = nullptr;

// 函数返回局部变量的指针int* bad() &#123;    int x = 42;    return &amp;x;  // x 在函数返回后已销毁，调用者拿到的是悬垂指针&#125;

double freeint* p = new int(42);int* q = p;    // 两个指针指向同一块内存delete p;delete q;      // 崩溃：同一块内存被释放两次

解决方案：用 unique_ptr 明确所有权，从根本上避免”谁该 delete”的混乱。
